mapper.select:
SELECT id, strategy_name_en AS strategyNameEn, from_date AS fromDate, to_date AS toDate,
       initial_cash AS initialCash, objective, validation_mode AS validationMode,
       target_monthly_return AS targetMonthlyReturn, target_is_guarantee AS targetIsGuarantee,
       status, message, created_at AS createdAt, updated_at AS updatedAt
FROM quant_experiment_run
WHERE 1 = 1

    AND strategy_name_en = #{strategyNameEn}


    AND from_date >= #{fromDate}


    AND to_date <= #{toDate}


    AND status = #{status}

ORDER BY created_at DESC, id DESC

mapper.insert:
INSERT INTO quant_experiment_run (
    strategy_name_en, from_date, to_date, initial_cash, objective,
    validation_mode, target_monthly_return, target_is_guarantee, status, message
) VALUES (
    #{strategyNameEn}, #{fromDate}, #{toDate}, #{initialCash}, #{objective},
    #{validationMode}, #{targetMonthlyReturn}::numeric, #{targetIsGuarantee}, #{status}, #{message}
)

INSERT INTO quant_experiment_variant (
    run_id, variant_code, params, total_return, annualized_return,
    monthly_return, mdd, sharpe_ratio, turnover, total_cost,
    target_achieved, bias_check_status, overfit_score, promoted
) VALUES (
    #{runId}, #{variantCode}, #{params}::jsonb, #{totalReturn}::numeric, #{annualizedReturn}::numeric,
    #{monthlyReturn}::numeric, #{mdd}::numeric, #{sharpeRatio}::numeric, #{turnover}::numeric, #{totalCost},
    #{targetAchieved}, #{biasCheckStatus}, #{overfitScore}::numeric, #{promoted}
)

mapper.update:
UPDATE quant_experiment_variant
SET promoted = TRUE
WHERE run_id = #{runId}
  AND id = #{variantId}

